mapper.insert:
INSERT INTO servicegroup_meta(csp_type, csp_account, csp_instanceid, service_cd, service_nm, service_uid
, service_type, workspace_cd, vm_id, vm_uid, vm_nm, mci_id, mci_uid, mci_nm, instance_running_status)
VALUES

    (#{item.cspType}
       , #{item.cspAccount}
       , #{item.cspInstanceid}
       , #{item.serviceCd}
       , #{item.serviceNm}
       , #{item.serviceUid}
       , #{item.serviceType}
       , COALESCE(#{item.workspaceCd}, 'undefined')
       , #{item.vmId}
       , #{item.vmUid}
       , #{item.vmNm}
       , #{item.mciId}
       , #{item.mciUid}
       , #{item.mciNm}
       , #{item.instanceRunningStatus})


    ON DUPLICATE KEY UPDATE csp_account = values(csp_account)
                         , service_cd = values(service_cd)
                         , service_nm = values(service_nm)
                         , service_type = values(service_type)
                         , workspace_cd = values(workspace_cd)
                         , vm_id = values(vm_id)
                         , vm_uid = values(vm_uid)
                         , vm_nm = values(vm_nm)
                         , mci_id = values(mci_id)
                         , mci_uid = values(mci_uid)
                         , mci_nm = values(mci_nm)
                         , instance_running_status = values(instance_running_status)

mapper.select:
SELECT DISTINCT lineitem_resourceid
  FROM tbl_table_billing_detail_${yearMonth}
 WHERE lineitem_productcode = 'AmazonEKS'
   AND lineitem_resourceid LIKE #{pattern}

mapper.delete:
DELETE FROM servicegroup_meta
 WHERE csp_type = 'AWS'
   AND service_type = 'K8S'
   AND service_cd = #{serviceCd}
   AND vm_id = #{vmId}
   AND csp_instanceid != #{cspInstanceid}
   AND csp_instanceid NOT LIKE 'arn:aws:eks:%'
   AND csp_instanceid NOT LIKE 'i-%'
